import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createFileStore, DEFAULT_TEXT } from '../store.js'

function withTempDir(fn) {
  const dir = mkdtempSync(join(tmpdir(), 'hello-'))
  try {
    return fn(dir)
  } finally {
    rmSync(dir, { recursive: true, force: true })
  }
}

test('DEFAULT_TEXT is "hello world"', () => {
  assert.equal(DEFAULT_TEXT, 'hello world')
})

test('read() returns the default text when no file exists', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.equal(store.read(), 'hello world')
  })
})

test('write() then a new store instance reads the persisted text', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    createFileStore(file).write('bonjour')
    assert.equal(createFileStore(file).read(), 'bonjour')
  })
})

test('unicode and newlines round-trip byte-for-byte', () => {
  withTempDir((dir) => {
    const file = join(dir, 'hello.json')
    const text = 'héllo 🌍\nline2'
    createFileStore(file).write(text)
    assert.equal(createFileStore(file).read(), text)
  })
})

test('write() creates missing parent directories', () => {
  withTempDir((dir) => {
    const file = join(dir, 'data', 'nested', 'x.json')
    const store = createFileStore(file)
    store.write('deep')
    assert.equal(store.read(), 'deep')
  })
})

test('read() propagates a real IO error instead of returning the default', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.read())
  })
})

test('write() rejects non-string input with a TypeError', () => {
  withTempDir((dir) => {
    const store = createFileStore(join(dir, 'hello.json'))
    assert.throws(() => store.write(42), TypeError)
    assert.equal(store.read(), 'hello world')
  })
})

test('mkdirSync failures during write propagate', () => {
  withTempDir((dir) => {
    const blocker = join(dir, 'blocker')
    writeFileSync(blocker, 'not a directory')
    const store = createFileStore(join(blocker, 'hello.json'))
    assert.throws(() => store.write('x'))
  })
})

const el = document.querySelector('#text')
const statusEl = document.querySelector('#status')

const DEBOUNCE_MS = 400
const PULSE_MS = 1200

let debounceTimer = null
let pulseTimer = null
let pending = false

function setStatus(message, state) {
  statusEl.textContent = message
  statusEl.classList.remove('saving', 'saved', 'error')
  if (state) statusEl.classList.add(state)
}

function stamp() {
  const now = new Date()
  const hours = String(now.getHours()).padStart(2, '0')
  const minutes = String(now.getMinutes()).padStart(2, '0')
  return `${hours}:${minutes}`
}

function pulse() {
  for (const node of [statusEl, el]) node.classList.add('saved')
  clearTimeout(pulseTimer)
  pulseTimer = setTimeout(() => {
    for (const node of [statusEl, el]) node.classList.remove('saved')
  }, PULSE_MS)
}

async function save({ keepalive = false } = {}) {
  clearTimeout(debounceTimer)
  debounceTimer = null
  if (!pending) return
  pending = false

  try {
    const res = await fetch('/api/text', {
      method: 'PUT',
      body: JSON.stringify({ text: el.textContent }),
      keepalive,
    })
    if (!res.ok) throw new Error(`PUT /api/text responded ${res.status}`)
    setStatus(`Saved ${stamp()}`, 'saved')
    pulse()
  } catch (error) {
    pending = true
    console.error('Could not save the greeting:', error)
    setStatus('Not saved — will retry', 'error')
  }
}

function scheduleSave() {
  pending = true
  setStatus('Saving…', 'saving')
  clearTimeout(debounceTimer)
  debounceTimer = setTimeout(save, DEBOUNCE_MS)
}

el.addEventListener('input', scheduleSave)
el.addEventListener('keydown', (event) => {
  // The greeting is a single line; Enter would inject <div>/<br> nodes.
  if (event.key === 'Enter') event.preventDefault()
})
el.addEventListener('blur', () => {
  if (pending) save()
})
window.addEventListener('pagehide', () => {
  if (pending) save({ keepalive: true })
})

try {
  const res = await fetch('/api/text')
  if (!res.ok) throw new Error(`GET /api/text responded ${res.status}`)
  const { text } = await res.json()
  el.textContent = text
  setStatus('Type to edit')
} catch (error) {
  console.error('Could not load the greeting:', error)
  setStatus('Not loaded — showing default', 'error')
}

